/** Source/fact review is separate from production. Numeric/coding answers are
 * established by the independent queue and all120 full prefix trees. */
import assert from "node:assert/strict";
import type {GeneratedBody} from "../../src/core/generators/definition";
import {legacy2019Pm8SourceReview as source} from "./legacy-2019-pm8-source-review";
import {legacy2019Pm8PriorityOracle as queue,legacy2019Pm8ExhaustiveCost as optimum,legacy2019Pm8Program1Oracle as program1,legacy2019Pm8Program2Oracle as program2} from "./legacy-2019-pm8-model-oracle";
const freq=[[1,7,3,2],[1,9,2,1],[1,8,3,1],[2,8,2,1]],originalChoices=source.question1.originalCodeTables;
const include=(text:string,parts:readonly string[])=>parts.forEach(p=>assert(text.includes(p),"Missing source premise/reason: "+p));
export function assertLegacy2019Pm8Body(body:GeneratedBody,values:number[]){
 assert.equal(values.length,1);const v=values[0],f=freq[v];assert(f);assert.equal(body.correctIndex,undefined);assert.equal(body.contexts,undefined);assert.equal(body.choices.length,24);assert.deepEqual(body.answerParts?.map(p=>[p.id,p.label,p.choiceIds.length]),source.parts.map(p=>[`part-${p.id}`,`設問${p.subquestion} ${p.id}`,p.choices]));assert.deepEqual(body.answerParts![2].choiceIds,body.answerParts![3].choiceIds);assert.equal(new Set(body.answerParts!.flatMap(p=>p.choiceIds)).size,24);
 const text=body.prompt.filter(b=>b.type==="paragraph").map(b=>b.text).join("\n"),target=f.map((n,i)=>"ABCD"[i].repeat(n)).join("");include(text,["原冊子では問8は必須",source.example.text,"以下、文字列αという",`文字列“${target}”を`,"2ビットの固定長","小数第3位を四捨五入","子である節を常に二つ","子の節の値の和","親が作成されていない節を二つ","同じ値をもつ節が二つ以上","配列の先頭に近い要素","選択した順に左側の子、右側の子","最後の要素の次","親が作成されていない節が一つになるまで","左側の子をつなぐ枝に0","右側の子をつなぐ枝に1","順に左から並べた","文字列αの文字“B”のビット表現は“010”","全ての文字を(3)で得られたビット表現に置き換え","要素番号は0から始まる","十分に大きく","全ての要素は−1","節が葉のとき","leftと配列right","節が根のとき","parentの要素の値は−1","行番号19〜24","行番号25","昇順","節の値が同じときの順序は並べ替える前の順","行番号2の条件","再帰的に呼び出す","葉から根","現在の節が親の左側のときは0","右側の子のときは1","printは、引数で与えられた文字列を表示","参照本文『共通に使用される擬似言語の記述形式（原p3〜4）』"]);assert(!text.includes("文字列β"),"Beta is only an internal research label,not a source label");
 const tables=body.prompt.filter(b=>b.type==="table");assert.equal(tables.length,5);assert.deepEqual(tables[0].columns,["文字","A","B","C","D"]);assert.deepEqual(tables[0].rows,[["出現回数","10","2","4","3"]]);const expectedArgs=[[["size","整数型","入力／出力"],["parent[]","整数型","入力／出力"],["left[]","整数型","入力／出力"],["right[]","整数型","入力／出力"],["freq[]","整数型","入力／出力"]],[["size","整数型","入力"],["parent[]","整数型","入力"],["freq[]","整数型","入力"],["nsize","整数型","出力"],["node[]","整数型","出力"]],[["freq[]","整数型","入力"],["nsize","整数型","入力"],["node[]","整数型","入力／出力"]],[["k","整数型","入力"],["parent[]","整数型","入力"],["left[]","整数型","入力"]]];for(let i=1;i<5;i++){assert.deepEqual(tables[i].columns,["引数","データ型","入出力","説明"]);assert.deepEqual(tables[i].rows.map(r=>r.slice(0,3)),expectedArgs[i-1]);assert(tables[i].rows.every(r=>r[3].length>0));}
 const diagrams=body.prompt.filter(b=>b.type==="diagram");assert.equal(diagrams.length,6);assert.deepEqual(diagrams.map(b=>{assert(b.scene.kind==="source_figure");assert.deepEqual(b.scene.values,[0]);assert(b.alt.length>0);return b.scene.profile;}),["legacy-2019-huffman-alpha-tree","legacy-2019-huffman-alpha-path","legacy-2019-huffman-ratio","legacy-2019-huffman-alpha-arrays","legacy-2019-huffman-program1","legacy-2019-huffman-program2"]);
 const ref=queue(f);assert.equal(ref.cost,optimum(f));const aTables=body.choices.slice(0,4).map(bs=>{assert.equal(bs.length,1);const b=bs[0];assert(b.type==="table");assert.deepEqual(b.columns,["文字","A","B","C","D"]);assert.equal(b.rows.length,1);assert.equal(b.rows[0][0],"ビット表現");return b.rows[0].slice(1);});assert.deepEqual(aTables,[ref.codes,...originalChoices.slice(1).map(c=>[...c])]);assert.equal(aTables[1][0],aTables[1][2]+aTables[1][1],"Actual table maps A and CB to the same bits");assert.equal(aTables[1][0],"010");assert.equal(aTables[3][0],aTables[3][1]+aTables[3][2],"Actual table maps A and BC to the same bits");assert.equal(aTables[3][0],"100");const bChoices=body.choices.slice(4,8).map(bs=>{assert.equal(bs.length,1);assert(bs[0].type==="paragraph");assert.match(bs[0].text,/^0\.\d{2}$/);return bs[0].text;});const weighted=(c:readonly string[])=>f.reduce((n,x,i)=>n+x*c[i].length,0),round=(n:number)=>{const cents=Math.floor(n*100/26),remainder=n*100-cents*26;return((cents+(2*remainder>=26?1:0))/100).toFixed(2);};assert.deepEqual(bChoices,[round(weighted(aTables[3])),round(ref.cost),round(weighted(aTables[2])),"0.92"]);for(let i=0;i<3;i++)assert(Number(bChoices[i+1])-Number(bChoices[i])>=.03-1e-10);
 const remaining=body.choices.slice(8).map(bs=>{assert.equal(bs.length,1);assert(bs[0].type==="paragraph");return bs[0].text;});assert.deepEqual(remaining,[...source.cdChoices,...source.eChoices,...source.fChoices]);
 const alpha=program1([10,2,4,3],2,3);assert(alpha.status==="tree");const encoding=program2(alpha.parent,alpha.left,4,1);assert(encoding.status==="codes");assert.deepEqual(encoding.codes,["1","010","00","011"]);
 assert.deepEqual(body.partAnswers,[1,6,11,12,20,22].map((n,i)=>({kind:"choice",partId:`part-${"abcdef"[i]}`,choiceId:`choice-value-${n}`})));include(body.explanation,[`A=${f[0]}、B=${f[1]}、C=${f[2]}、D=${f[3]}`,`A=${ref.codes[0]}、B=${ref.codes[1]}、C=${ref.codes[2]}、D=${ref.codes[3]}`,`総ビット長は${ref.cost}`,`13×2=26`,`丸めた${bChoices[1]}`,"説明例αは別の文字列","AとCBがどちらも010","AとBCがどちらも100","接頭語をもつだけで常に復号不能とは限らず","cはnsize≧2","dはparent[i]<0","eはparent[k]≧0","fはleft[parent[k]]=k","根側から戻って0/1を出力する順序"]);
 assert(!body.explanation.includes("符号語の先頭が他の符号語になっている表は、文字の区切りを一意に復元できない"),"Do not generalize non-prefix-free into non-uniquely-decodable");
}
